!function(){"use strict";window.__hymns=[{id:"afta7_fay",kind:"تمجيد",title:"افتح فاي بالتسبيح",sub:"تمجيد — «يا ربي يسوع المسيح»",src:{name:"موقع الأنبا تكلا (St-Takla.org) — تمجيد «افتح فاي بالتسبيح» (التنسيق الأول)",url:"https://st-takla.org/Lyrics-Spiritual-Songs/Words-of-Coptic-Alhan-Tasbeha-Kodas/Arabic-Coptic-08-El-Dorah-El-Orthodoxiah/Orthodox-Praises__068-Afta7-Fay-Bel-Tasabeeh.html"},review:{status:"needs-review",note:"منقول من لقطة شاشة للصفحة؛ التهجئة كما في المصدر، ويحتاج مطابقة نهائية مع الصفحة قبل الاعتماد"},refrain:null,lines:["افتح فاي بالتسبيح واقول بقلب جريح يا رب يسوع المسيح أعطني لسان فصيح","لكي اسبح اسمك واشكر فضل انعامك يا رب يسوع المسيح علمني احكامك","قدوس اسمك وعجيب وممجد فى قديسيك يا ربي يسوع المسيح ارحم صنعه يديك","مستحق ومستوجب التسابيح والتماجيد يا ربي يسوع المسيح تسبيحك حلو لذيذ","صرخت طول النهار مديت نحوك يدى يا ربي يسوع المسيح اسمك حلو عندى","جعلت اتكالى عليك يا رب لا تهملني يا ربي يسوع المسيح لا تتخلى عنى","روحك القدوس لا تنزعه منى يا ربي يسوع المسيح بمعونتك اشملنى","جرحنى العدو بسهام وجرحه فى حاق اعطنى جسدك مرهم ودمك هو لى ترياق","سبع مرات كل يوم ابارك اسمك يا ربي يسوع المسيح اجعلنى من قسمك","اشتاق نفسى اليك كالارض العطشانة يا ربي يسوع المسيح برحمتك لا تنسانه","لا تنسى بيعتنا املأها من خيراتك يا ربي يسوع المسيح ثبتها بشهاداتك","شهداتك حلوه فى حلقى كالشهد داخل فمى يا ربي يسوع المسيح اغسلنى من اثمى","نشكر صانع الخيرات نسجد للرب يسوع المسيح رب القوات فلنركع له بخشوع","رتب فينا احكامك وبقولك ثبتنا يا رب يسوع المسيح ارفع شأن كنيستنا","ارفع شأن المسيحيين فى جميع المسكونه يا رب يسوع المسيح اشملهم بمعونه","وان كنا فقراء من المال اسمك هو يكفينا يا ربي يسوع المسيح وصلاحك يغنينا","يجب لك التسبيح ينبغى لك البركات يا رب يسوع المسيح ينبوع كل الخيرات","يارب خلص شعبك وبارك ميراثك ارفع شأنهم باسمك وراثهم ملكوتك","ملكوتك يا إلهي ملكوت أبديه وسيادتك يا ملكى سياده ازليه","ازليه ومرتفعه وعجيبه هى افعالك يا رب يسوع المسيح سيد كل ممالك","ممالك الدنيا تزول والمال كل فانى يا رب يسوع المسيح ملك غير متناهى","تنتهى الممالك تفنى كنوز الامرا يا رب يسوع المسيح انت كنز الفقراء","فقراء شعبك اغنيهم والمرضى اسقيهم والايتام ربيهم من فضلك اغنيهم","اغنيهم من فضلك واوف كل المديونين يا رب يسوع المسيح انت غنى المحتاجين","ان كنا محتاجين فلنا دره ثمينه لنا الحجر الكريم يسوع غالى القيمه","غالى القيمه وكريم اغلى من الدنيا تمام اسمه يسوع المسيح الغافر كل اثام","غافر كل الذنوب سامع لمن يدعوه تعترف له كل الشعوب والملوك يسبحونه","سبحوه يا كل الامم مجدوه يا كل الشعوب يا ربي يسوع المسيح انت تبلغنا المطلوب","مطلوبنا ملكوتك ومراحمك موجوده يا ربي يسوع المسيح يا من طبعه الجوده","صاحب الجوده وكريم وليس له قط نظير يا ربي يسوع المسيح على الكل بصير","بصير ومتطلع علينا بتدابيرك يا ربي يسوع المسيح لا تحوجنا لغيرك","لا نعرف غيرك اله بانجيلك صدقنا انت هو ابن الله فى ايمانك ثبتنا","ثبتنا على الايمان وانهضنا من كل ملل يا ربي يسوع المسيح باسمك نتهلل","نتهلل بالالحان ونرتل بالمزامير يا ربي يسوع المسيح تسبيحك بهجه وسرور","سرورنا تسابيحك بهجتنا هى مجدك يا ربي يسوع المسيح العظمه لك وحدك","لك وحدك انا اخطيت وصنعت الشر امامك لتصدق فى اقوالك وتغلب فى احكامك","احكامك حق وعدل ومراحمك متسعه يا ربي يسوع المسيح ارحم نفسى المتضعه","اتضعت امام مجدك واتكلت على اقوالك يا ربي يسوع المسيح لا تطرحنى على شمالك","على شمالك لا توقفنى مع القوم الاشرار أسألك ان تقبلنى كما قبلت العشار","أصرخ بصوت العشار وانا برأس مطاطى اللهم اغفر لى الاوزار فانا عبدك الخاطى","الخطيه من طبعى وانت طبعك الاحسان ليس عبد بلا خطيه ولا سيد بلا غفران","الغفران من عندك والرحمه هى من قبلك يا ربي يسوع المسيح اهدينى الى سبلك","سبلك تاهت عنى والعمر فرغ منى أسألك ان تقبلنى والتوبه اعطنى","اعطينى التوبه والغفران ونقينى من كل عيوبى يا ربي يسوع المسيح اغفر لى ذنوبى","ذنوبى ثقلت فوق رأسى كحمل ثقيل قاسى يا ربي يسوع المسيح اشف كل حواسى","مراحمك يا الهى هى كثيره جدا مراحمك يا الهى لا يحصى لها عدد","مراحمك يا الهى اكثر من نبات الارض مراحمك يا الهى قد فاقت كل عدد","مراحمك يا الهى كقطرات الامطار مراحمك يا الهى اكثر من رمل البحار","مراحمك يا الهى كينابيع المياه مراحمك يا الهى كالانهار الجاريه","يا رب ارحم نفسى يا رب خلصنى يارب امحى اثمى بصلاحك اذكرنى","قدوس قدوس قدوس الله رب الصباؤت الخالق كل النفوس ورازقهم بالقوه","نسألك يا ملكنا ادم رئاسه بطركنا وشركاؤه اسافقتنا آمين الليلويا"]},{id:"epsalia_talabtak",kind:"إبصالية",title:"إبصالية «طلبتك من عمق قلبي»",sub:"«يا ربي يسوع أعنِّي»",src:{name:"نص مقدَّم من المستخدم (المصدر الأصلي غير محدد)"},review:{status:"needs-review",note:"النص كما أرسله المستخدم؛ المصدر الأصلي غير محدد، ومطابقته لـ«إبصالية آدام» ويوم الأحد غير مؤكدة"},refrain:["يا ربي يسوع أعنِّي","يا ربي يسوع المسيح أعنِّي"],lines:["طلبتك من عمق قلبي\nيا ربي يسوع أعنِّي\nحل عني رباطات الخطية\nيا ربي يسوع المسيح أعنِّي","كن لي معيناً لكي تخلصني\nيا ربي يسوع أعنِّي\nصلاحك فليدركني سريعاً\nيا ربي يسوع المسيح أعنِّي","ظلِّل عليَّ بظِل جناحيك\nيا ربي يسوع أعنِّي\nفي ستة أيام صنعت كل الخليقة\nيا ربي يسوع المسيح أعنِّي","سبع مرات في اليوم أبارك إسمك\nيا ربي يسوع أعنِّي\nها كل البرية تمجد إسمك\nيا ربي يسوع المسيح أعنِّي","لك الربوبية والسلطان\nيا ربي يسوع أعنِّي\nأسرع يا إلهي لتخلصني\nيا ربي يسوع المسيح أعنِّي","كل ركبة تجثو أمامك\nيا ربي يسوع أعنِّي\nكل الألسنة معاً تبارك إسمك\nيا ربي يسوع المسيح أعنِّي","إصرف وجهك عن خطاياي\nيا ربي يسوع أعنِّي\nجميع آثامي يا الله إمحها\nيا ربي يسوع المسيح أعنِّي","أنت تعرف أفكاري وتفحص كليتي\nيا ربي يسوع أعنِّي\nقلباً طاهراً أخلقه فيَّ\nيا ربي يسوع المسيح أعنِّي","روحك القدوس لا تنزعه منِّي\nيا ربي يسوع أعنِّي\nأمِّل سمعك إليَّ وإستجب لي عاجلاً\nيا ربي يسوع المسيح أعنِّي","قرِّر ليَّ ناموساً في طريق عدلك\nيا ربي يسوع أعنِّي\nملكوتك يا إلهي ملكوت أبدي\nيا ربي يسوع المسيح أعنِّي","أنت إبن الله آمنت بك\nيا ربي يسوع أعنِّي\nيا حامل خطية العالم إرحمني\nيا ربي يسوع المسيح أعنِّي","إغفر ليَّ كثرة آثامي\nيا ربي يسوع أعنِّي\nكل الأنفس معاً تبارك إسمك\nيا ربي يسوع المسيح أعنِّي","تأنَّ عليَّ ولا تهلكني سريعاً\nيا ربي يسوع أعنِّي\nأقوم وقت السحر لأبارك إسمك\nيا ربي يسوع المسيح أعنِّي","حلوٌ هو نيرك وحملك خفيف\nيا ربي يسوع أعنِّي\nفي زمن مقبول إستجب ليَّ\nيا ربي يسوع المسيح أعنِّي","محبوب هو إسمك القدوس\nيا ربي يسوع أعنِّي\nفرِّق عنِّي كل الأبالسة\nيا ربي يسوع المسيح أعنِّي","إغرس فيَّ ثمرة بِرَك\nيا ربي يسوع أعنِّي","أعطنا سلامك الحقيقي\nوإغفر لنا خطايانا\nيا ربي يسوع المسيح أعنِّي"]}]}();